    INSERT INTO [dbo].[COURSE] (id, code, name, description, min_age, max_age, image_url, video_url, benefits, facility_images, rating, reviews, status, created_at, updated_at) VALUES
    (1, 'FGM', N'Finger Math - Toán Bàn Tay Tư Duy', N'Phương pháp tính nhẩm nhanh từ 0 đến 99 bằng hai bàn tay, kích thích phản xạ và hứng thú toán học cho trẻ nhỏ.', 4, 7, 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'["Ph\u00E1t tri\u1EC3n c\u00E2n b\u1EB1ng c\u1EA3 hai b\u00E1n c\u1EA7u n\u00E3o","T\u0103ng kh\u1EA3 n\u0103ng t\u1EADp trung v\u00E0 ghi nh\u1EDB h\u00ECnh \u1EA3nh","T\u1EF1 tin t\u00EDnh nh\u1EA9m v\u00E0 gi\u1EA3i quy\u1EBFt b\u00E0i to\u00E1n t\u01B0 duy"]', N'["https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=600","https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=600"]', 4.8, 369, 'ACTIVE', '2025-10-01 08:00:00', '2026-07-15 08:00:00'),
    (2, 'SRB-BASIC', N'Soroban Cơ Bản - Bàn Tính Số Học', N'Làm quen bàn tính Soroban chuẩn Nhật Bản, thành thạo thao tác hạt và công thức Anh bạn nhỏ, Anh bạn lớn.', 6, 10, 'https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=800', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'["Ph\u00E1t tri\u1EC3n c\u00E2n b\u1EB1ng c\u1EA3 hai b\u00E1n c\u1EA7u n\u00E3o","T\u0103ng kh\u1EA3 n\u0103ng t\u1EADp trung v\u00E0 ghi nh\u1EDB h\u00ECnh \u1EA3nh","T\u1EF1 tin t\u00EDnh nh\u1EA9m v\u00E0 gi\u1EA3i quy\u1EBFt b\u00E0i to\u00E1n t\u01B0 duy"]', N'["https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=600","https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=600"]', 4.8, 438, 'ACTIVE', '2025-10-06 08:00:00', '2026-07-15 08:00:00'),
    (3, 'SRB-ADV', N'Soroban Nâng Cao - Ảo Tính Anzan', N'Luyện ảo tính Anzan không cần bàn tính, thực hiện phép nhân chia nhiều chữ số và chuỗi tính nhẩm tốc độ cao.', 7, 13, 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=800', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'["Ph\u00E1t tri\u1EC3n c\u00E2n b\u1EB1ng c\u1EA3 hai b\u00E1n c\u1EA7u n\u00E3o","T\u0103ng kh\u1EA3 n\u0103ng t\u1EADp trung v\u00E0 ghi nh\u1EDB h\u00ECnh \u1EA3nh","T\u1EF1 tin t\u00EDnh nh\u1EA9m v\u00E0 gi\u1EA3i quy\u1EBFt b\u00E0i to\u00E1n t\u01B0 duy"]', N'["https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=600","https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=600"]', 4.7, 121, 'ACTIVE', '2025-10-11 08:00:00', '2026-07-15 08:00:00'),
    (4, 'LOGIC', N'Toán Tư Duy Logic & Suy Luận', N'Phát triển tư duy phản biện, giải toán đố bằng sơ đồ Bar Model, quy luật dãy số và chuẩn bị kỳ thi SASMO/Kangaroo.', 7, 14, 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'["Ph\u00E1t tri\u1EC3n c\u00E2n b\u1EB1ng c\u1EA3 hai b\u00E1n c\u1EA7u n\u00E3o","T\u0103ng kh\u1EA3 n\u0103ng t\u1EADp trung v\u00E0 ghi nh\u1EDB h\u00ECnh \u1EA3nh","T\u1EF1 tin t\u00EDnh nh\u1EA9m v\u00E0 gi\u1EA3i quy\u1EBFt b\u00E0i to\u00E1n t\u01B0 duy"]', N'["https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=600","https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=600"]', 4.9, 423, 'ACTIVE', '2025-10-16 08:00:00', '2026-07-15 08:00:00'),
    (5, 'PRE-PRI', N'Tiền Tiểu Học - Hành Trang Vào Lớp 1', N'Xây dựng nền tảng nhận diện con số, so sánh, hình khối cơ bản và rèn thói quen tập trung trước khi vào lớp 1.', 4, 6, 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'["Ph\u00E1t tri\u1EC3n c\u00E2n b\u1EB1ng c\u1EA3 hai b\u00E1n c\u1EA7u n\u00E3o","T\u0103ng kh\u1EA3 n\u0103ng t\u1EADp trung v\u00E0 ghi nh\u1EDB h\u00ECnh \u1EA3nh","T\u1EF1 tin t\u00EDnh nh\u1EA9m v\u00E0 gi\u1EA3i quy\u1EBFt b\u00E0i to\u00E1n t\u01B0 duy"]', N'["https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=600","https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=600"]', 4.9, 154, 'ACTIVE', '2025-10-21 08:00:00', '2026-07-15 08:00:00');
