    (3188, 319, 'TEACHER', 20, 'TEXT', N'Chào phụ huynh, tuần này bé tiến bộ rõ rệt ở tốc độ tính nhẩm không bàn tính ạ!', NULL, 1, '2026-07-10 05:35:06'),
    (3189, 319, 'PARENT', 95, 'TEXT', N'Thầy/cô cho em hỏi tuần này bé học công thức Anh bạn lớn có theo kịp lớp không ạ?', NULL, 0, '2026-07-11 06:35:06'),
    (3190, 319, 'TEACHER', 20, 'TEXT', N'Dạ vâng em đã ghi nhận ạ, phụ huynh nhớ nhắc bé mang theo bàn tính và phiếu bài tập nhé.', NULL, 0, '2026-07-12 05:35:06'),
    (3191, 320, 'PARENT', 55, 'TEXT', N'Thầy/cô ơi cho em hỏi lịch ôn tập kiểm tra cuối cấp độ vào ngày nào ạ?', NULL, 1, '2026-02-28 11:10:11'),
    (3192, 320, 'TEACHER', 7, 'TEXT', N'Chào phụ huynh, tuần này bé tiến bộ rõ rệt ở tốc độ tính nhẩm không bàn tính ạ!', NULL, 1, '2026-02-28 19:10:11'),
    (3193, 320, 'PARENT', 55, 'TEXT', N'Thầy/cô cho em hỏi tuần này bé học công thức Anh bạn lớn có theo kịp lớp không ạ?', NULL, 1, '2026-02-28 21:10:11'),
    (3194, 320, 'TEACHER', 7, 'TEXT', N'Dạ vâng em đã ghi nhận ạ, phụ huynh nhớ nhắc bé mang theo bàn tính và phiếu bài tập nhé.', NULL, 1, '2026-03-01 16:10:11'),
    (3195, 320, 'PARENT', 55, 'TEXT', N'Em cảm ơn thầy/cô đã gửi nhận xét chi tiết tiến độ học tập của con nhé!', NULL, 1, '2026-03-02 05:10:11'),
    (3196, 320, 'TEACHER', 7, 'TEXT', N'Lịch đánh giá cuối cấp độ sẽ diễn ra vào buổi thứ 16, trung tâm sẽ gửi thông báo nhắc trước 3 ngày ạ.', NULL, 1, '2026-03-02 17:10:11'),
    (3197, 320, 'PARENT', 55, 'TEXT', N'Dạ chào thầy/cô, hôm nay bé đi học về rất vui và làm hết bài tập bàn tính rồi ạ.', NULL, 1, '2026-03-03 12:10:11'),
    (3198, 320, 'TEACHER', 7, 'TEXT', N'Phụ huynh yên tâm, bé nắm bài nhanh và rất hăng hái giơ tay phát biểu trên lớp.', NULL, 1, '2026-03-04 00:10:11'),
    (3199, 320, 'PARENT', 55, 'TEXT', N'Chiều thứ 5 nhà em có việc bận nên bé xin vào muộn 10 phút ạ.', NULL, 1, '2026-03-04 15:10:11'),
    (3200, 320, 'TEACHER', 7, 'TEXT', N'Em vừa giao thêm bộ bài tập chuỗi phép tính trên ứng dụng, bé luyện 10 phút mỗi tối là rất tốt ạ.', NULL, 1, '2026-03-05 05:10:11');
